{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "The closest analogue (7z) shares the thiophene-sulfonyl-isoxazole core and has >80% oral availability in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Tiagabine has an absolute oral bioavailability of 90% in fasting healthy volunteers, showing that high F is achievable despite low structural similarity to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir, a sulfonamide-containing heterocycle, shows 75% oral bioavailability after a single 100 mg dose in humans, supporting high F for the sulfonamide-heterocycle class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Lumiracoxib, a coxib-like anti-inflammatory, has an absolute oral bioavailability of 74.0 ± 8.6% in healthy subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue shares the thiophene-sulfonyl-isoxazole core and has >80% human oral bioavailability; multiple other drugs in the evidence set show absolute F values of 74–90%. The only low-F estimate (azosemide 10%) is methodologically weak and outweighed. Therefore the query is predicted to have F ≥20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The closest analogue has moderate Morgan similarity (0.44); the specific effects of the benzodioxole and chloro-isoxazole substituents on absorption are not directly measured.",
    "The azosemide low-F estimate is based on weak urinary excretion data and was not used as affirmative low evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

